oxy_webhelp_navlinks = {"fs_host_management_for_filesets-d39307e29045":{"topics":[{"title":"Fileset host details","shortdesc":"<p class=\"shortdesc\">For every fileset host, <span class=\"ph\">RSC<\/span> displays important details         including the list of filesets on the host and the SLA Domains protecting the         filesets.<\/p>","href":"saas\/fs_fileset_host_details.html","attributes":{"data-id":"fs_fileset_host_details"},"menu":{"hasChildren":false},"tocID":"fs_fileset_host_details-d39307e29058","topics":[]},{"title":"Adding a fileset host","shortdesc":"<p class=\"shortdesc\">To begin managing and protecting filesets on a host, add the host to a Rubrik         cluster.<\/p>","href":"saas\/fs_adding_fileset_host.html","attributes":{"data-id":"fs_adding_fileset_host"},"menu":{"hasChildren":false},"tocID":"fs_adding_fileset_host-d39307e29072","topics":[]},{"title":"Removing a fileset host","shortdesc":"<p class=\"shortdesc\">You can delete the host from the Rubrik cluster to stop protecting the fileset data         on a host.<\/p>","href":"saas\/fs_removing_a_fileset_host.html","attributes":{"data-id":"fs_removing_a_fileset_host"},"menu":{"hasChildren":false},"tocID":"fs_removing_a_fileset_host-d39307e29083","topics":[]},{"title":"Fileset host management actions","shortdesc":"<p class=\"shortdesc\">For every fileset host, <span class=\"ph\">RSC<\/span> provides the ability to check the         connection status, update the certificate, and edit the identity of the host.<\/p>","href":"saas\/fs_fileset_host_management_actions.html","attributes":{"data-id":"fs_fileset_host_management_actions"},"menu":{"hasChildren":false},"tocID":"fs_fileset_host_management_actions-d39307e29094","topics":[]}]}};